"""
Flask 应用工厂
框架代码，不包含具体业务逻辑
"""
import os
from flask import Flask, render_template
from flask_sqlalchemy import SQLAlchemy
from flask_cors import CORS
from configuration import load_config

db = SQLAlchemy()

# 项目根目录
BASE_DIR = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))


def create_app(config_name=None):
    """应用工厂函数"""
    # 设置模板路径
    template_dir = os.path.join(BASE_DIR, 'templates')
    app = Flask(__name__, template_folder=template_dir)

    # 加载配置
    if config_name:
        app.config.from_object(config_name)
    else:
        app.config.from_object(load_config())

    # 初始化扩展
    db.init_app(app)

    # CORS 支持
    CORS(app)

    # ==== 在这里注册业务蓝图 ====

    @app.route('/blogs')
    def blog_list():
        return render_template('blog_list.html')

    @app.route('/blogs/<int:id>')
    def blog_detail(id):
        return render_template('blog_detail.html')
    from app.routes.blog_routes import blog_bp
    app.register_blueprint(blog_bp, url_prefix='/api/blogs')

    @app.route('/blogs/new')
    def blog_new():
        return render_template('blog_new.html')
    @app.route('/blogs/<int:id>/edit')
    def blog_edit(id):
        return render_template('blog_edit.html', blog={'id': id, 'title': 'Sample Title', 'description': 'Sample Description'})

    @app.route('/error')
    def error_page():
        return render_template('error.html')

    # ==============================

    # 初始化数据库模型
    from app.models import Blog

    # 首页路由
    @app.route('/')
    def index():
        return render_template('index.html')

    # 健康检查
    @app.route('/health')
    def health():
        return {'status': 'ok'}

    # 创建数据库表
    with app.app_context():
        db.create_all()

    return app

import os
from flask import Blueprint, request, jsonify
from werkzeug.utils import secure_filename
from app.models.blog import Blog
from app import db

UPLOAD_FOLDER = 'app/static/uploads'

blog_bp = Blueprint('blog', __name__)

@blog_bp.route('/', methods=['GET'])
def get_blogs():
    blogs = Blog.query.all()
    return jsonify([blog.to_dict() for blog in blogs])

@blog_bp.route('/<int:id>', methods=['GET'])
def get_blog(id):
    blog = Blog.query.get_or_404(id)
    return jsonify(blog.to_dict())

@blog_bp.route('/', methods=['POST'])
def create_blog():
    title = request.form.get('title')
    description = request.form.get('description')
    image = request.files.get('image')

    if not title or not description:
        return jsonify({'error': 'Title and description are required'}), 400

    image_path = None
    if image:
        filename = secure_filename(image.filename)
        image.save(os.path.join(UPLOAD_FOLDER, filename))
        image_path = f'/static/uploads/{filename}'

    blog = Blog(title=title, description=description, image_path=image_path)
    db.session.add(blog)
    db.session.commit()

    return jsonify(blog.to_dict()), 201

@blog_bp.route('/<int:id>', methods=['PUT'])
def update_blog(id):
    blog = Blog.query.get_or_404(id)

    title = request.form.get('title')
    description = request.form.get('description')
    image = request.files.get('image')

    if title:
        blog.title = title
    if description:
        blog.description = description
    if image:
        filename = secure_filename(image.filename)
        image.save(os.path.join(UPLOAD_FOLDER, filename))
        blog.image_path = f'/static/uploads/{filename}'

    db.session.commit()

    return jsonify(blog.to_dict())

@blog_bp.route('/<int:id>', methods=['DELETE'])
def delete_blog(id):
    blog = Blog.query.get_or_404(id)
    db.session.delete(blog)
    db.session.commit()

    return jsonify({'message': 'Blog deleted successfully'})
